from tri import build
A = ['uk', 'pl', 'en']
build(34, dict(
 title='Мати драконів|Matka smoków|Mother of Dragons',
 scene='Далеко за Вузьким морем кхал Дрого слабне від рани. Дейенерис просить чарівницю врятувати його, але ціна виявляється страшною: Дрого живий, але більше не прокидається по-справжньому. Дені відпускає його й складає велике багаття. Вона кладе на нього три кам\'яні яйця драконів і сама входить у вогонь. Уранці люди знаходять її живою серед попелу — а на її плечах сидять три маленькі дракони.|Daleko za Wąskim Morzem khal Drogo słabnie od rany. Daenerys prosi czarownicę o ratunek, ale cena okazuje się straszna: Drogo żyje, lecz już nigdy naprawdę się nie budzi. Dany pozwala mu odejść i układa wielki stos. Kładzie na nim trzy kamienne smocze jaja i sama wchodzi w ogień. Rano ludzie znajdują ją żywą wśród popiołu — a na jej ramionach siedzą trzy małe smoki.|Far beyond the Narrow Sea, Khal Drogo grows weak from a wound. Daenerys asks a sorceress to save him, but the price is terrible: Drogo lives, but never truly wakes again. Dany lets him go and builds a great pyre. She places three stone dragon eggs on it and walks into the fire herself. In the morning her people find her alive among the ashes, with three small dragons on her shoulders.',
 prev='Робба проголосили Королем Півночі. Тепер до його табору їдуть посли й купці з усього світу — і кожен приносить новини.|Robba ogłoszono Królem Północy. Teraz do jego obozu przybywają posłowie i kupcy z całego świata — i każdy przynosi wieści.|Robb has been proclaimed King in the North. Now envoys and merchants from all over the world come to his camp, and each one brings news.',
 cards=[('Дейенерис Таргарієн', 'Daenerys Targaryen', 'Остання з роду драконів. Увійшла у вогонь і вийшла з нього.|Ostatnia z rodu smoków. Weszła w ogień i z niego wyszła.|The last of the dragon line. She walked into the fire and came out of it.'),
        ('Кхал Дрого', 'Khal Drogo', 'Великий воїн, якого не зміг перемогти жоден ворог — лише рана.|Wielki wojownik, którego nie pokonał żaden wróg — tylko rana.|A great warrior no enemy could defeat. Only a wound did.'),
        ('Сер Джора Мормонт', 'Ser Jorah Mormont', 'Вигнанець із Півночі. Перший схилив коліно перед Матір\'ю драконів.|Wygnaniec z Północy. Pierwszy ukląkł przed Matką Smoków.|An exile from the North. The first to kneel before the Mother of Dragons.'),
        ('Мірі Маз Дуур', 'Mirri Maz Duur', 'Чарівниця, що взяла плату, якої ніхто не чекав.|Czarownica, która wzięła zapłatę, jakiej nikt się nie spodziewał.|A sorceress who took a price that no one expected.'),
        ('Купець із Пентосу', 'A merchant from Pentos', 'Привіз до табору Робба новину, у яку важко повірити.|Przywiózł do obozu Robba wieść, w którą trudno uwierzyć.|He brought news to Robb\'s camp that is hard to believe.')],
 gname={'en': 'Formal register and emphatic do / did: I do believe, She did survive|Rejestr formalny i emfatyczne do / did|Formal register, emphatic do',
        'pl': 'Forma grzecznościowa: Pan / Pani, wołacz (Panie, Wasza Miłość), proszę + bezokolicznik|Forma grzecznościowa i wołacz|Polish polite address and vocative',
        'uk': 'Ввічливе звертання: ви / Ви, кличний відмінок (пане, ваша милосте), прошу + інфінітив|Ukraińska forma grzecznościowa i wołacz|Ukrainian polite address and vocative'},
 where='Ти сидиш за столом у королівському наметі. Перед тобою — купець у шовковому плащі.|Siedzisz przy stole w królewskim namiocie. Przed tobą kupiec w jedwabnym płaszczu.|You are sitting at a table in the royal tent. In front of you is a merchant in a silk cloak.',
 role='До табору приїхав купець із Пентосу. Він каже, що привіз новину, важливу для всього Вестеросу. Король Робб наказує тобі записати його слова офіційно — як свідчення. Ти маєш говорити ввічливо й чітко, як писар короля.|Do obozu przyjechał kupiec z Pentos. Mówi, że przywiózł wieść ważną dla całego Westeros. Król Robb każe ci spisać jego słowa oficjalnie — jako zeznanie. Musisz mówić uprzejmie i jasno, jak królewski pisarz.|A merchant from Pentos has arrived at the camp. He says he brings news that matters to all of Westeros. King Robb orders you to take down his words officially, as a statement. You must speak politely and clearly, like the king\'s scribe.',
 sc=[('Свідчення купця|Zeznanie kupca|The merchant\'s statement', 'свідчення|zeznanie|statement;пане|panie|sir;прошу|proszę|please;сідати|siadać|to sit down;ім\'я|imię|name;правда|prawda|truth', [
   'Прошу, [сідайте/сідає/сідати], пане.|Proszę [usiąść/siada/siądzie], panie.|Please [do sit/does sit/did sat] down, sir.',
   'Як вас [звати], пане?|Jak ma pan na [imię]?|What is your [name], sir?',
   'Я запишу ваше [свідчення] для короля.|Spiszę pańskie [zeznanie] dla króla.|I will write down your [statement] for the king.',
   'Прошу говорити лише [правду].|Proszę mówić tylko [prawdę].|Please speak only the [truth].',
   'Дякую, [пане], продовжуйте.|Dziękuję, [panie], proszę kontynuować.|Thank you, [sir]. Please go on.',
   'Ви [справді/справжній/справа] бачили її на власні очі?|Czy pan [naprawdę/prawdziwy/prawda] widział ją na własne oczy?|You [did see/did saw/does see] her with your own eyes?']),
  ('Рана кхала|Rana khala|The khal\'s wound', 'рана|rana|wound;кхал|khal|khal;чарівниця|czarownica|sorceress;намет|namiot|tent;слабнути|słabnąć|to grow weak;ціна|cena|price', [
   'Кхал отримав [рану] в простому бою.|Khal odniósł [ranę] w zwykłej walce.|The khal got a [wound] in an ordinary fight.',
   'З кожним днем він почав [слабнути].|Z każdym dniem zaczął [słabnąć].|Day by day he began to [grow weak].',
   'Дейенерис покликала [чарівницю] на допомогу.|Daenerys wezwała na pomoc [czarownicę].|Daenerys called a [sorceress] for help.',
   'Ніхто не знав, якою буде [ціна].|Nikt nie wiedział, jaka będzie [cena].|No one knew what the [price] would be.',
   'Усю ніч у [наметі] співали дивні пісні.|Całą noc w [namiocie] śpiewano dziwne pieśni.|All night strange songs were sung in the [tent].',
   'Великий [кхал] так і не прокинувся по-справжньому.|Wielki [khal] nigdy naprawdę się nie obudził.|The great [khal] never truly woke up.']),
  ('Багаття|Stos|The pyre', 'багаття|stos|pyre;яйце|jajo|egg;попіл|popiół|ashes;плече|ramię|shoulder;вогонь|ogień|fire;світанок|świt|dawn', [
   'Дені наказала скласти велике [багаття].|Dany kazała ułożyć wielki [stos].|Dany ordered a great [pyre] to be built.',
   'На нього поклали три кам\'яні [яйця].|Położono na nim trzy kamienne [jaja].|Three stone [eggs] were placed on it.',
   'Вона сама ввійшла у [вогонь].|Sama weszła w [ogień].|She walked into the [fire] herself.',
   'Люди чекали до самого [світанку].|Ludzie czekali aż do [świtu].|The people waited until [dawn].',
   'Вони знайшли її живою серед [попелу].|Znaleźli ją żywą wśród [popiołu].|They found her alive among the [ashes].',
   'На її [плечі] сидів маленький дракон.|Na jej [ramieniu] siedział mały smok.|A little dragon sat on her [shoulder].'])],
 rule={'uk': 'Ввічливо звертаємося на «ви» (у листі — «Ви») і дієслово ставимо в множину: «Ви бачили?». Кличний відмінок: пан → пане, король → королю, милість → милосте («ваша милосте»). Прохання: прошу + інфінітив («Прошу говорити правду») або наказовий спосіб на -те («сідайте»). Наголос на правді: справді, таки («Вона таки вижила»).',
       'pl': 'Grzecznie mówimy Pan / Pani + czasownik w 3. osobie: „Czy pan widział?”, „Proszę usiąść”. Wołacz: pan → panie, król → królu, Wasza Miłość bez zmian. Prośba: proszę + bezokolicznik („Proszę mówić prawdę”). Nacisk: naprawdę, jednak, przecież („Ona jednak przeżyła”).',
       'en': 'Formal English: full forms, polite requests (Would you be so kind as to…, Please do…). Emphatic do / does / did + base verb stresses that something is true, often against doubt: “She did survive.” “I do believe you.” “Please do sit down.” The main verb stays in the base form: did survive, not did survived.'},
 gram=['Прошу, [сідайте/сідаєте/сідали], пане.|Proszę [usiąść/siedzi/siedział], panie.|Please [do sit/does sit/did sat] down, sir.',
  'Чи ви справді [бачили/бачив/бачите] драконів, пане?|Czy pan naprawdę [widział/widziałeś/widzisz] smoki?|You [did see/did saw/do saw] the dragons, then?',
  'Я дякую вам, [пане/пан/пана].|Dziękuję panu, [panie/pan/pana].|I [do thank/does thank/did thanked] you, sir.',
  'Ваша [милосте/милість/милістю], купець чекає.|Wasza [Miłość/Miłości/Miłością], kupiec czeka.|Your [Grace/Graces/Gracing], the merchant is waiting.',
  'Вона [таки/так/такий] вийшла з вогню живою.|Ona [jednak/tak/taki] wyszła z ognia żywa.|She [did come/did came/does came] out of the fire alive.',
  'Прошу [говорити/говорить/говорив] повільніше.|Proszę [mówić/mówi/mówił] wolniej.|Please [do speak/does speak/did spoke] more slowly.',
  'Пане, чи могли б ви [повторити/повторив/повторює]?|Czy mógłby pan [powtórzyć/powtórzył/powtarza]?|Sir, [could you/you could/did you could] repeat that?',
  'Мій [королю/король/королем], це правда.|Mój [królu/król/królem], to prawda.|My [lord/lords/lordly], it is the truth.',
  'Я [справді/справа/справжня] вірю вам, пане.|[Naprawdę/Prawdziwy/Prawda] panu wierzę.|I [do believe/does believe/did believed] you, sir.',
  'Чи знаєте [ви/ти/вони], що сталося далі?|Czy [pan/ty/oni] wie, co stało się dalej?|[Do you/Does you/You does] know what happened next?',
  'Дракони [справді/справа/справжнє] народилися з каменю.|Smoki [naprawdę/prawda/prawdziwe] urodziły się z kamienia.|The dragons [did hatch/did hatched/do hatched] from stone.',
  'Прошу [підписати/підписав/підпише] ваше свідчення.|Proszę [podpisać/podpisał/podpisze] swoje zeznanie.|[Please do sign/Please does sign/Please did sign] your statement.'],
 rt='Офіційне свідчення купця з Пентосу|Oficjalne zeznanie kupca z Pentos|Official statement of a merchant from Pentos',
 read=['Записано в таборі короля Робба, на [прохання] його милості.|Spisano w obozie króla Robba, na [prośbę] Jego Miłości.|Recorded in King Robb\'s camp, at the [request] of His Grace.',
  'Пане купцю, прошу назвати ваше [ім\'я].|Panie kupcze, proszę podać swoje [imię].|Merchant, please state your [name].',
  '«Я — Іліо з Пентосу, і я торгую [шовком]», — сказав він.|„Jestem Illio z Pentos i handluję [jedwabiem]” — powiedział.|“I am Illio of Pentos, and I trade in [silk],” he said.',
  'Ваша милосте, я був у кхаласарі Дрого цієї [весни].|Wasza Miłość, byłem w khalasarze Drogo tej [wiosny].|Your Grace, I was in Drogo\'s khalasar this [spring].',
  'Великий кхал отримав рану й почав [слабнути].|Wielki khal odniósł ranę i zaczął [słabnąć].|The great khal was wounded and began to [weaken].',
  'Його дружина покликала [чарівницю] з чужого народу.|Jego żona wezwała [czarownicę] z obcego ludu.|His wife called a [sorceress] from a foreign people.',
  'Чарівниця [таки] врятувала йому життя, але не душу.|Czarownica [jednak] ocaliła mu życie, ale nie duszę.|The sorceress [did] save his life, but not his soul.',
  'Кхал більше не говорив, не їздив верхи й нікого не [впізнавав].|Khal już nie mówił, nie jeździł konno i nikogo nie [poznawał].|The khal no longer spoke, rode or [recognised] anyone.',
  'Тоді королева відпустила його, тихо й [лагідно].|Wtedy królowa pozwoliła mu odejść, cicho i [łagodnie].|Then the queen let him go, quietly and [gently].',
  'Вона наказала скласти багаття вище за [намет].|Kazała ułożyć stos wyższy niż [namiot].|She ordered a pyre built higher than a [tent].',
  'На багаття поклали три [яйця] драконів із каменю.|Na stosie położono trzy smocze [jaja] z kamienia.|Three dragon [eggs] of stone were laid on the pyre.',
  'Пане, ви кажете, що вона сама [ввійшла] у вогонь?|Panie, mówi pan, że sama [weszła] w ogień?|Sir, you say she [walked] into the fire herself?',
  '«Так, ваша милосте. Я [справді] бачив це на власні очі».|„Tak, Wasza Miłość. [Naprawdę] widziałem to na własne oczy”.|“Yes, Your Grace. I [did] see it with my own eyes.”',
  'Усю ніч вогонь [горів] так, що було світло, як удень.|Całą noc ogień [płonął] tak, że było jasno jak w dzień.|All night the fire [burned] so brightly that it was as light as day.',
  'На світанку люди знайшли її серед [попелу].|O świcie ludzie znaleźli ją wśród [popiołu].|At dawn the people found her among the [ashes].',
  'Вона була жива, а на її плечах [сиділи] три дракони.|Była żywa, a na jej ramionach [siedziały] trzy smoki.|She was alive, and three dragons [sat] on her shoulders.',
  'Сер Джора першим став перед нею на [коліно].|Ser Jorah pierwszy ukląkł przed nią na [kolano].|Ser Jorah was the first to go down on one [knee] before her.',
  'Підписано купцем у присутності королівського [писаря].|Podpisano przez kupca w obecności królewskiego [pisarza].|Signed by the merchant in the presence of the king\'s [scribe].'],
 chk=[('Звідки приїхав купець?|Skąd przyjechał kupiec?|Where did the merchant come from?', ['З Пентосу|Z Pentos|From Pentos', 'З Дорну|Z Dorne|From Dorne', 'З Вінтерфелла|Z Winterfell|From Winterfell']),
  ('Що сталося з кхалом Дрого?|Co stało się z khalem Drogo?|What happened to Khal Drogo?', ['Він вижив, але більше не прокинувся по-справжньому|Przeżył, ale nigdy naprawdę się nie obudził|He lived but never truly woke again', 'Він повністю видужав|Całkiem wyzdrowiał|He fully recovered', 'Він утік у степ|Uciekł na step|He ran away into the grass sea']),
  ('Що поклали на багаття?|Co położono na stosie?|What was put on the pyre?', ['Три кам\'яні яйця|Trzy kamienne jaja|Three stone eggs', 'Корону кхала|Koronę khala|The khal\'s crown', 'Сто мечів|Sto mieczy|A hundred swords']),
  ('Що знайшли на світанку?|Co znaleziono o świcie?|What was found at dawn?', ['Живу Дейенерис і трьох драконів|Żywą Daenerys i trzy smoki|Daenerys alive with three dragons', 'Лише попіл|Tylko popiół|Only ashes', 'Порожній намет|Pusty namiot|An empty tent']),
  ('Як писар має говорити з купцем?|Jak pisarz ma mówić z kupcem?|How must the scribe speak to the merchant?', ['Ввічливо й офіційно|Uprzejmie i oficjalnie|Politely and formally', 'Грубо й коротко|Ostro i krótko|Rudely and briefly', 'Як із давнім другом|Jak ze starym przyjacielem|Like an old friend'])],
 qq='Купець закінчив. Король Робб дивиться на тебе: «Постав йому останні питання — ввічливо, як належить. Я хочу бути певним».|Kupiec skończył. Król Robb patrzy na ciebie: „Zadaj mu ostatnie pytania — uprzejmie, jak należy. Chcę mieć pewność”.|The merchant has finished. King Robb looks at you: “Ask him the last questions, politely, as is proper. I want to be certain.”',
 quest=[('Робб: Спитай, чи він бачив це сам.|Robb: Zapytaj, czy widział to sam.|Robb: Ask whether he saw it himself.', 'Пане, чи ви справді бачили це на власні очі?|Panie, czy naprawdę widział pan to na własne oczy?|Sir, did you really see this with your own eyes?', 'Ей, ти бачив це сам?|Ej, widziałeś to sam?|Hey, you saw it yourself, yes?'),
  ('Купець: Так, бачив, присягаюся.|Kupiec: Tak, widziałem, przysięgam.|Merchant: Yes, I did, I swear it.', 'Дякую вам, пане. Я вам вірю.|Dziękuję panu. Wierzę panu.|Thank you, sir. I do believe you.', 'Дякую тобі. Я вірю ти.|Dziękuję ci. Wierzę ty.|Thank you. I does believe you.'),
  ('Робб: Спитай, скільки там драконів.|Robb: Zapytaj, ile jest smoków.|Robb: Ask how many dragons there are.', 'Прошу сказати, скільки там драконів, пане.|Proszę powiedzieć, ile jest smoków, panie.|Would you tell us how many dragons there are, sir?', 'Скажи, скільки драконів!|Mów, ile smoków!|Tell how many dragon!'),
  ('Робб: Подякуй і відпусти його.|Robb: Podziękuj i odpraw go.|Robb: Thank him and let him go.', 'Дякуємо, пане. Прошу відпочити в нашому таборі.|Dziękujemy, panie. Proszę odpocząć w naszym obozie.|Thank you, sir. Please do rest in our camp.', 'Дякую. Іди відпочивай.|Dzięki. Idź odpoczywać.|Thanks. Go rests.')],
 qend='Коли купець виходить, у наметі довго ніхто не говорить. Нарешті Кейтлін каже тихо: «Дракони… Ми воюємо за трон, а світ уже змінюється». Ти дописуєш останній рядок і ставиш печатку.|Kiedy kupiec wychodzi, w namiocie długo nikt się nie odzywa. W końcu Catelyn mówi cicho: „Smoki… Walczymy o tron, a świat już się zmienia”. Dopisujesz ostatnią linijkę i przykładasz pieczęć.|When the merchant leaves, no one in the tent speaks for a long time. At last Catelyn says quietly: “Dragons… We are fighting for a throne, and the world is already changing.” You write the last line and set the seal.',
 speak=['Прошу, сідайте, пане.|Proszę usiąść, panie.|Please do sit down, sir.', 'Вона таки вийшла з вогню живою.|Ona jednak wyszła z ognia żywa.|She did come out of the fire alive.'],
 fin=('Напиши офіційний лист від імені короля Робба (90+ слів) до лорда Півночі про новину з-за моря. Використай ввічливе звертання (мілорде, ви / Ви, прошу…) і слова, що підкреслюють правду (справді, таки).|Napisz oficjalny list w imieniu króla Robba (90+ słów) do lorda Północy o wieści zza morza. Użyj formy grzecznościowej (milordzie, Pan, proszę…) i słów podkreślających prawdę (naprawdę, jednak).|Write an official letter on behalf of King Robb (90+ words) to a lord of the North about the news from across the sea. Use formal language (My lord, would you…, please do…) and emphatic do / did.',
      'Мілорде, прошу вислухати… Купець справді бачив… Вона таки вижила… Прошу Вас бути пильним…|Milordzie, proszę wysłuchać… Kupiec naprawdę widział… Ona jednak przeżyła… Proszę Pana o czujność…|My lord, I do ask you to listen… The merchant did see… She did survive… Please do stay watchful…')), A)
